SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-SXVI_NOTE_2A', code: '', label: 'Phần XVI — Chú giải 2 a', section: 'XVI', chapter: '', level: None, description: '(a) Các bộ phận đã được chi tiết tại nhóm nào đó của Chương 84 hoặc 85 (trừ các nhóm 84.09, 84.31, 84.48, 84.66, 84.73, 84.87, 85.03, 85.22, 85.29, 85.38 và 85.48) được phân loại vào nhóm đó trong mọi trường hợp;'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-SXVI_NOTE_2B', code: '', label: 'Phần XVI — Chú giải 2 b', section: 'XVI', chapter: '', level: None, description: '(b) Các bộ phận khác, nếu phù hợp để chỉ sử dụng hoặc chủ yếu sử dụng cho các loại máy cụ thể, hoặc cho một số loại máy cùng nhóm (kể cả máy thuộc nhóm 84.79 hoặc 85.43) được phân loại theo nhóm của các máy cụ thể đó hoặc vào nhóm thích hợp như 84.09, 84.31, 84.48, 84.66, 84.73, 85.03, 85.22, 85.29 hoặc 85.38. Tuy nhiên, bộ phận phù hợp để chủ yếu sử dụng cho các hàng hóa thuộc các nhóm 85.17 và 85.25 đến 85.28 được phân loại vào nhóm 85.17; và bộ phận phù hợp để chỉ sử dụng hoặc chủ yếu sử dụng cho hàng hoá của nhóm 85.24 được phân loại vào nhóm 85.29;'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-SXVI_NOTE_2C', code: '', label: 'Phần XVI — Chú giải 2 c', section: 'XVI', chapter: '', level: None, description: '(c) Tất cả các bộ phận khác được phân loại trong nhóm thích hợp như 84.09, 84.31, 84.48, 84.66, 84.73, 85.03, 85.22, 85.29 hoặc 85.38 hoặc, nếu không thì, phân loại vào nhóm 84.87 hoặc 85.48.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-SXVI_NOTE_3', code: '', label: 'Phần XVI — Chú giải 3', section: 'XVI', chapter: '', level: None, description: 'Trừ khi có yêu cầu cụ thể khác, các loại máy liên hợp gồm hai hoặc nhiều máy lắp ghép với nhau thành một thiết bị đồng bộ và các loại máy khác được thiết kế để thực hiện hai hoặc nhiều chức năng khác nhau hoặc bổ trợ lẫn nhau được phân loại theo bộ phận chính hoặc máy thực hiện chức năng chính.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-SXVI_NOTE_4', code: '', label: 'Phần XVI — Chú giải 4', section: 'XVI', chapter: '', level: None, description: 'Khi một máy (kể cả một tổ hợp máy) gồm các bộ phận cấu thành riêng lẻ (dù tách biệt hoặc được liên kết với nhau bằng ống, bằng bộ phận truyền, bằng cáp điện hoặc bằng bộ phận khác) để thực hiện một chức năng được xác định rõ đã quy định chi tiết tại một trong các nhóm của Chương 84 hoặc Chương 85, thì toàn bộ máy đó phải được phân loại vào nhóm phù hợp với chức năng xác định của máy.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-SXVI_NOTE_5', code: '', label: 'Phần XVI — Chú giải 5', section: 'XVI', chapter: '', level: None, description: 'Theo mục đích của Chú giải này, khái niệm “máy” có nghĩa là bất kỳ máy, máy móc, thiết bị, bộ dụng cụ hoặc dụng cụ đã nêu trong các nhóm của Chương 84 hoặc 85.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-SXVI_NOTE_6A_INTRO', code: '', label: 'Phần XVI — Chú giải 6 A', section: 'XVI', chapter: '', level: None, description: '(A) Trong toàn bộ Danh mục này, khái niệm “phế liệu và phế thải điện và điện tử” có nghĩa là các cụm linh kiện điện và điện tử, tấm mạch in, và các sản phẩm điện hoặc điện tử:'}) $$) as (v agtype);
