SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-SXVI_NOTE_6B', code: '', label: 'Phần XVI — Chú giải 6 B', section: 'XVI', chapter: '', level: None, description: '(B) Các lô hàng hỗn hợp gồm “phế liệu và phế thải điện và điện tử” và phế liệu và phế thải khác được phân loại vào nhóm 85.49.'}) $$) as (v agtype);
