SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_1C', code: '', label: 'Chương 84 — Chú giải 1 c', section: 'XVI', chapter: '84', level: None, description: '(c) Đồ thủy tinh dùng cho phòng thí nghiệm (nhóm 70.17); máy, thiết bị hoặc các sản phẩm khác dùng cho các mục đích kỹ thuật hoặc các bộ phận của chúng, bằng thủy tinh (nhóm 70.19 hoặc 70.20);'}) $$) as (v agtype);
