SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_1H', code: '', label: 'Chương 84 — Chú giải 1 h', section: 'XVI', chapter: '84', level: None, description: '(h) Máy quét sàn cơ khí thao tác bằng tay, không có động cơ (nhóm 96.03).'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_2_MAIN', code: '', label: 'Chương 84 — Chú giải 2', section: 'XVI', chapter: '84', level: None, description: 'Theo nội dung của Chú giải 3 Phần XVI và Chú giải 11 của Chương này, máy móc hoặc thiết bị thỏa mãn mô tả của một hoặc nhiều nhóm từ 84.01 đến 84.24, hoặc nhóm 84.86 và đồng thời thỏa mãn mô tả của một hoặc nhiều nhóm từ 84.25 đến 84.80 thì được phân loại vào một nhóm thích hợp trong số các nhóm từ 84.01 đến 84.24 hoặc 84.86, mà không được phân loại vào một trong các nhóm 84.25 đến 84.80.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_2A', code: '', label: 'Chương 84 — Chú giải 2 A', section: 'XVI', chapter: '84', level: None, description: '(A) Tuy nhiên, nhóm 84.19 không bao gồm: (i) Máy ươm hạt giống, máy ấp trứng gia cầm và thiết bị sưởi ấm gia cầm mới nở (nhóm 84.36); (ii) Máy làm ẩm hạt (nhóm 84.37); (iii) Máy khuếch tán dùng để chiết xuất đường quả (nhóm 84.38); (iv) Máy để xử lý nhiệt đối với sợi dệt, vải hoặc các sản phẩm dệt (nhóm 84.51); hoặc (v) Thiết bị cho phòng thí nghiệm hoặc máy móc, thiết bị, được thiết kế để hoạt động bằng cơ khí, trong đó sự thay đổi nhiệt cho dù cần thiết chỉ là phần bổ sung.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_2B', code: '', label: 'Chương 84 — Chú giải 2 B', section: 'XVI', chapter: '84', level: None, description: '(B) Nhóm 84.22 không bao gồm: (i) Máy khâu dùng để đóng túi hoặc các loại bao bì tương tự (nhóm 84.52); hoặc (ii) Máy văn phòng thuộc nhóm 84.72.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_2C', code: '', label: 'Chương 84 — Chú giải 2 C', section: 'XVI', chapter: '84', level: None, description: '(C) Nhóm 84.24 không bao gồm: (i) Máy in phun mực (nhóm 84.43); hoặc (ii) Máy cắt bằng tia nước (nhóm 84.56).'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_3', code: '', label: 'Chương 84 — Chú giải 3', section: 'XVI', chapter: '84', level: None, description: 'Máy công cụ để gia công loại vật liệu nào đó mà nó đáp ứng mô tả trong nhóm 84.56 và đồng thời đáp ứng mô tả trong nhóm 84.57, 84.58, 84.59, 84.60, 84.61, 84.64 hoặc 84.65 được phân loại trong nhóm 84.56.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_4', code: '', label: 'Chương 84 — Chú giải 4', section: 'XVI', chapter: '84', level: None, description: 'Nhóm 84.57 chỉ áp dụng cho máy công cụ để gia công kim loại, trừ máy tiện (kể cả trung tâm gia công tiện), loại này có thể thực hiện được các kiểu thao tác gia công khác nhau: (a) bằng cách thay đổi công cụ công tác tự động từ hộp đựng hoặc tương tự theo đúng chương trình gia công (trung tâm gia công), (b) bằng việc sử dụng tự động, đồng thời hoặc tuần tự các đầu gia công tổ hợp khác nhau để tác động lên một vật gia công ở vị trí cố định (máy kết cấu nguyên khối (một vị trí gia công)), hoặc (c) bằng cách di chuyển tự động vật gia công đến các đầu gia công tổ hợp khác nhau (máy gia công chuyển dịch đa vị trí).'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_5', code: '', label: 'Chương 84 — Chú giải 5', section: 'XVI', chapter: '84', level: None, description: 'Theo mục đích của nhóm 84.62, một \"dây chuyền xẻ cuộn\" dùng cho các sản phẩm dạng phẳng là một dây chuyền xử lý gồm một máy xả cuộn, một máy làm phẳng cuộn, một máy xẻ và máy quấn cuộn. Một “dây chuyền cắt xén thành đoạn” dùng cho các sản phẩm dạng phẳng là một dây chuyền xử lý bao gồm một máy xả cuộn, một máy làm phẳng cuộn và một máy cắt xén.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_6A', code: '', label: 'Chương 84 — Chú giải 6 A', section: 'XVI', chapter: '84', level: None, description: '(A) Theo mục đích của nhóm 84.71, khái niệm \"máy xử lý dữ liệu tự động\" là máy có khả năng: (i) Lưu trữ chương trình xử lý hoặc các chương trình và ít nhất lưu trữ các dữ liệu cần ngay cho việc thực hiện chương trình; (ii) Lập chương trình tùy theo yêu cầu của người sử dụng; (iii) Thực hiện các phép tính số học tùy theo yêu cầu của người sử dụng; và (iv) Thực hiện một chương trình xử lý đòi hỏi máy phải biến đổi quy trình thực hiện, bằng các quyết định lôgíc trong quá trình chạy chương trình, mà không có sự can thiệp của con người.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_6B', code: '', label: 'Chương 84 — Chú giải 6 B', section: 'XVI', chapter: '84', level: None, description: '(B) Máy xử lý dữ liệu tự động có thể ở dạng hệ thống bao gồm một số lượng biến thiên các khối chức năng riêng biệt.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_6C', code: '', label: 'Chương 84 — Chú giải 6 C', section: 'XVI', chapter: '84', level: None, description: '(C) Theo đoạn (D) và (E) dưới đây, khối chức năng được xem như là bộ phận của một hệ thống xử lý dữ liệu tự động nếu thoả mãn tất cả các điều kiện sau: (i) Là loại chỉ sử dụng hoặc chủ yếu sử dụng trong hệ thống xử lý dữ liệu tự động; (ii) Có khả năng kết nối với bộ xử lý trung tâm hoặc trực tiếp hoặc thông qua một hoặc nhiều khối chức năng khác; và (iii) Có khả năng tiếp nhận hoặc cung cấp dữ liệu theo định dạng (mã hoặc tín hiệu) mà hệ thống có thể sử dụng được. Những khối chức năng riêng biệt của máy xử lý dữ liệu tự động được phân loại vào nhóm 84.71. Tuy nhiên, bàn phím, thiết bị nhập tọa độ X-Y và bộ (ổ) lưu trữ dạng đĩa đáp ứng các điều kiện của đoạn (C) (ii) và (C) (iii) ở trên, trong mọi trường hợp đều được phân loại như khối chức năng của nhóm 84.71.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_6D', code: '', label: 'Chương 84 — Chú giải 6 D', section: 'XVI', chapter: '84', level: None, description: '(D) Nhóm 84.71 không bao gồm các hàng hóa sau đây khi nó được trình bày riêng rẽ, ngay cả khi nó đáp ứng tất cả các điều kiện trong Chú giải 6 (C) nêu trên: (i) Máy in, máy photocopy, máy fax, có hoặc không liên hợp; (ii) Thiết bị truyền dẫn hoặc nhận âm thanh, hình ảnh hoặc dữ liệu khác, kể cả thiết bị để giao tiếp trong mạng có dây hoặc không dây (như mạng nội bộ hoặc diện rộng); (iii) Loa và micro; (iv) Camera truyền hình, camera kỹ thuật số và camera ghi hình ảnh; (v) Màn hình và máy chiếu, không kết hợp thiết bị thu truyền hình.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_6E', code: '', label: 'Chương 84 — Chú giải 6 E', section: 'XVI', chapter: '84', level: None, description: '(E) Các máy kết hợp hoặc làm việc kết hợp với một máy xử lý dữ liệu tự động và thực hiện một chức năng riêng biệt không phải là chức năng xử lý dữ liệu được phân loại vào nhóm thích hợp với chức năng tương ứng của chúng hoặc, nếu không, sẽ được phân loại vào các nhóm còn lại.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_7', code: '', label: 'Chương 84 — Chú giải 7', section: 'XVI', chapter: '84', level: None, description: 'Không kể những đề cập khác, nhóm 84.82 áp dụng cho các bi thép đã đánh bóng, có dung sai lớn nhất và nhỏ nhất so với đường kính danh nghĩa không quá 1% hoặc không quá 0,05 mm, theo mức dung sai nhỏ hơn. Các loại bi thép khác được xếp vào nhóm 73.26.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_8', code: '', label: 'Chương 84 — Chú giải 8', section: 'XVI', chapter: '84', level: None, description: 'Theo yêu cầu của phân loại, máy móc sử dụng cho hai mục đích trở lên được phân loại theo mục đích sử dụng chính và mục đích này được coi như mục đích sử dụng duy nhất. Theo Chú giải 2 của Chương này và Chú giải 3 của Phần XVI, loại máy mà công dụng chính của nó không được mô tả trong bất kỳ nhóm nào hoặc không có công dụng nào là chủ yếu, nếu nội dung nhóm không có yêu cầu khác, thì được phân loại vào nhóm 84.79. Nhóm 84.79 cũng bao gồm các máy để làm thừng hoặc cáp (ví dụ, máy bện, xoắn hoặc đánh cáp) bằng dây kim loại, sợi dệt hoặc bất kỳ vật liệu nào khác hoặc bằng các vật liệu kết hợp.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_9', code: '', label: 'Chương 84 — Chú giải 9', section: 'XVI', chapter: '84', level: None, description: 'Theo nội dung của nhóm 84.70, khái niệm “loại bỏ túi” chỉ áp dụng cho máy móc có kích thước không quá 170 mm X 100 mm X 45 mm.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_10', code: '', label: 'Chương 84 — Chú giải 10', section: 'XVI', chapter: '84', level: None, description: 'Theo mục đích của nhóm 84.85, khái niệm “công nghệ sản xuất bồi đắp” (còn được gọi là công nghệ in 3D) có nghĩa là sự hình thành các vật thể hữu hình, dựa trên mô hình kỹ thuật số, bằng cách đắp chồng và tạo lớp liên tiếp, và hợp nhất (consolidation) và đóng rắn (solidification), từ vật liệu (ví dụ, kim loại, nhựa hoặc gốm). Theo Chú giải 1 Phần XVI và Chú giải 1 Chương 84, các máy đáp ứng mô tả của nhóm 84.85 được phân loại trong nhóm này và không phân loại vào nhóm khác của Danh mục.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_11A', code: '', label: 'Chương 84 — Chú giải 11 A', section: 'XVI', chapter: '84', level: None, description: '(A) Chú giải 12 (a) và 12 (b) Chương 85 cũng áp dụng đối với khái niệm “thiết bị bán dẫn” và “mạch điện tử tích hợp”, như đã được sử dụng trong Chú giải này và trong nhóm 84.86. Tuy nhiên, theo mục đích của Chú giải này và của nhóm 84.86, khái niệm “thiết bị bán dẫn” cũng bao gồm các thiết bị bán dẫn nhạy sáng (cảm quang) và đi-ốt phát quang (LED).'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_11B', code: '', label: 'Chương 84 — Chú giải 11 B', section: 'XVI', chapter: '84', level: None, description: '(B) Theo mục đích của Chú giải này và của nhóm 84.86, khái niệm “sản xuất màn hình dẹt” bao gồm chế tạo các lớp nền (các lớp cơ bản cấu thành) của tấm dẹt màn hình. Nó không bao gồm công đoạn gia công, sản xuất kính hoặc lắp ráp các tấm mạch in hoặc các bộ phận điện tử khác vào tấm dẹt màn hình. Khái niệm “màn hình dẹt” không áp dụng cho loại sử dụng công nghệ ống đèn hình ca-tốt.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_NOTE_11C', code: '', label: 'Chương 84 — Chú giải 11 C', section: 'XVI', chapter: '84', level: None, description: '(C) Nhóm 84.86 cũng bao gồm những máy móc và thiết bị chỉ sử dụng hoặc chủ yếu sử dụng để: (i) sản xuất hoặc sửa chữa màn (khuôn in) và lưới quang; (ii) lắp ghép thiết bị bán dẫn hoặc các mạch điện tử tích hợp; (iii) bộ phận nâng, giữ, xếp vào hoặc tháo dỡ khối bán dẫn, tấm bán dẫn mỏng, thiết bị bán dẫn, mạch điện tử tích hợp và màn hình dẹt.'}) $$) as (v agtype);
