SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH84_SUBNOTE_2', code: '', label: 'Chương 84 — Chú giải phân nhóm 2', section: 'XVI', chapter: '84', level: None, description: 'Theo mục đích của phân nhóm 8471.49, khái niệm “hệ thống” nghĩa là các máy xử lý dữ liệu tự động mà các khối chức năng của nó đáp ứng các điều kiện nêu tại Chú giải 6 (C) Chương 84 và nó gồm ít nhất một bộ xử lý trung tâm, một bộ nhập (ví dụ, bàn phím hoặc bộ quét), và một bộ xuất (ví dụ, một bộ hiển thị hoặc máy in).'}) $$) as (v agtype);
