SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_5', code: '', label: 'Chương 85 — Chú giải 5', section: 'XVI', chapter: '85', level: None, description: 'Theo mục đích của nhóm 85.17, thuật ngữ \"điện thoại thông minh\" có nghĩa là điện thoại dùng cho mạng di động tế bào, được trang bị hệ điều hành di động được thiết kế để thực hiện các chức năng của máy xử lý dữ liệu tự động như tải xuống và chạy nhiều ứng dụng đồng thời, kể cả ứng dụng của bên thứ ba, và có hoặc không tích hợp các tính năng khác như camera kỹ thuật số và hệ thống hỗ trợ điều hướng.'}) $$) as (v agtype);
