SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_6A', code: '', label: 'Chương 85 — Chú giải 6 a', section: 'XVI', chapter: '85', level: None, description: '(a) \"Các thiết bị lưu trữ bền vững, thể rắn (sản phẩm lưu trữ bán dẫn không bị xoá dữ liệu khi không còn nguồn điện cung cấp)\" (ví dụ, “thẻ nhớ flash (flash memory cards)” hoặc “thẻ lưu trữ điện tử flash (flash electronic storage cards)”) là thiết bị lưu trữ gắn với đầu kết nối (đầu cắm nối), có chứa trong cùng một vỏ một hoặc nhiều linh kiện nhớ flash (ví dụ, “FLASH E2PROM”) dưới dạng mạch tích hợp lắp ghép trên tấm mạch in. Chúng có thể gồm phần điều khiển dưới dạng mạch tích hợp và phần tử thụ động riêng biệt, như tụ điện và điện trở;'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_6B', code: '', label: 'Chương 85 — Chú giải 6 b', section: 'XVI', chapter: '85', level: None, description: '(b) Khái niệm “thẻ thông minh” nghĩa là thẻ được gắn bên trong một hoặc nhiều mạch điện tử tích hợp (bộ vi xử lý, bộ nhớ truy cập ngẫu nhiên (RAM) hoặc bộ nhớ chỉ đọc (ROM)) ở dạng các chip. Các thẻ này có thể bao gồm các tiếp điểm, dải từ tính hoặc ăng ten gắn bên trong nhưng không chứa bất cứ phần tử chủ động hoặc thụ động nào khác.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_7', code: '', label: 'Chương 85 — Chú giải 7', section: 'XVI', chapter: '85', level: None, description: 'Theo mục đích của nhóm 85.24, “mô-đun màn hình dẹt” dùng để chỉ các thiết bị hoặc dụng cụ để hiển thị thông tin, được trang bị tối thiểu một màn hiển thị, được thiết kế để lắp vào các sản phẩm thuộc các nhóm khác trước khi sử dụng. Màn hình hiển thị cho các mô-đun màn hình dẹt bao gồm, nhưng không giới hạn ở dạng dẹt, cong, linh hoạt, ở dạng có thể gập lại hoặc co giãn. Mô-đun màn hình dẹt có thể kết hợp thêm các chi tiết, bao gồm cả những chi tiết cần thiết để nhận tín hiệu video và phân bổ các tín hiệu đó đến các điểm ảnh trên màn hiển thị. Tuy nhiên, nhóm 85.24 không bao gồm các mô-đun hiển thị được trang bị các thành phần để chuyển đổi tín hiệu video (ví dụ, IC điều chỉnh tỷ lệ, IC giải mã hoặc bộ xử lý ứng dụng) hoặc mang đặc tính của hàng hóa thuộc các nhóm khác. Để phân loại mô-đun màn hình dẹt được định nghĩa trong Chú giải này, nhóm 85.24 sẽ được ưu tiên hơn bất kỳ nhóm nào khác trong Danh mục.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_8', code: '', label: 'Chương 85 — Chú giải 8', section: 'XVI', chapter: '85', level: None, description: 'Theo mục đích của nhóm 85.34 “mạch in” là mạch được tạo ra trên một tấm cách điện bằng một quy trình in mạch nào đó (ví dụ, rập nổi, mạ, khắc axit) hoặc bằng kỹ thuật tạo “mạch điện màng”, các phần tử dẫn điện, các tiếp điểm hoặc các thành phần dùng cho mạch in khác (ví dụ, cuộn cảm, điện trở, tụ điện) đơn lẻ hoặc được liên kết theo sơ đồ mẫu đã thiết kế trước, trừ các phần tử có thể phát (tạo ra), chỉnh lưu, điều biến hoặc khuếch đại tín hiệu điện (ví dụ, các phần tử bán dẫn). Thuật ngữ “mạch in” không bao gồm mạch đã tổ hợp với các phần tử trừ các phần tử đã được hình thành trong quá trình in mạch, và cũng không bao gồm điện trở, tụ điện hoặc cuộn cảm đơn lẻ hoặc bố trí ghép nối riêng biệt. Tuy nhiên, những mạch in này có thể gắn với phần tử kết nối không qua quá trình in mạch. Mạch điện màng mỏng hoặc dày bao gồm phần tử chủ động và thụ động hợp thành trong cùng một qui trình công nghệ được phân loại trong nhóm 85.42.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_9', code: '', label: 'Chương 85 — Chú giải 9', section: 'XVI', chapter: '85', level: None, description: 'Theo mục đích của nhóm 85.36, “đầu nối dùng cho sợi quang, bó sợi quang hoặc cáp quang” nghĩa là đầu nối chỉ dùng để ghép nối đối đầu một cách cơ học các sợi quang trong hệ thống đường truyền kỹ thuật số. Chúng không có chức năng khác, như khuếch đại, tái tạo hoặc biến đổi tín hiệu.'}) $$) as (v agtype);
