SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_11A', code: '', label: 'Chương 85 — Chú giải 11 a', section: 'XVI', chapter: '85', level: None, description: '(a) “Mô-đun đi-ốt phát quang (LED)” là nguồn sáng điện dựa trên các đi-ốt phát quang (LED) được bố trí trong các mạch điện và chứa thêm các phần tử như phần tử điện, cơ, nhiệt hoặc quang học. Chúng cũng chứa các phần tử chủ động riêng biệt, phần tử thụ động riêng biệt, hoặc các sản phẩm thuộc nhóm 85.36 hoặc 85.42 nhằm mục đích cung cấp nguồn điện hoặc điều khiển nguồn điện. Mô-đun đi-ốt phát quang (LED) không có đầu đèn được thiết kế để cho phép dễ dàng lắp đặt hoặc thay thế trong đèn điện và đảm bảo tiếp xúc cơ và điện.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_11B', code: '', label: 'Chương 85 — Chú giải 11 b', section: 'XVI', chapter: '85', level: None, description: '(b) “Đèn đi-ốt phát quang (LED)” là nguồn sáng điện gồm một hoặc nhiều mô-đun LED có chứa thêm các phần tử như phần tử điện, cơ, nhiệt hoặc quang học. Sự khác biệt giữa mô-đun đi-ốt phát quang (LED) và bóng đèn đi-ốt phát quang (LED) là đèn (lamp) có đầu đèn được thiết kế để cho phép dễ dàng lắp đặt hoặc thay thế trong đèn (luminaire) và đảm bảo tiếp xúc cơ và điện.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_12_INTRO', code: '', label: 'Chương 85 — Chú giải 12', section: 'XVI', chapter: '85', level: None, description: 'Theo mục đích của nhóm 85.41 và 85.42:'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_12A_I', code: '', label: 'Chương 85 — Chú giải 12 a(i)', section: 'XVI', chapter: '85', level: None, description: '(a) (i) “Thiết bị bán dẫn” là các thiết bị bán dẫn mà hoạt động của nó phụ thuộc vào sự thay đổi của điện trở suất khi áp dụng điện trường hoặc các bộ chuyển đổi dựa trên chất bán dẫn. Các thiết bị bán dẫn cũng có thể bao gồm nhiều phần tử được lắp ráp, có hoặc không được trang bị các chức năng phụ trợ của thiết bị chủ động và thụ động.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_12A_I_TRANSDUCER', code: '', label: 'Chương 85 — Chú giải 12 a(i)-transducer', section: 'XVI', chapter: '85', level: None, description: 'Theo mục đích của định nghĩa này, “Bộ chuyển đổi dựa trên chất bán dẫn” là cảm biến dựa trên chất bán dẫn, bộ truyền động dựa trên chất bán dẫn, bộ cộng hưởng dựa trên chất bán dẫn và bộ tạo dao động dựa trên chất bán dẫn, là các loại thiết bị dựa trên chất bán dẫn riêng biệt, thực hiện một chức năng theo bản chất của nó, có thể chuyển đổi bất kỳ loại hiện tượng vật lý hoặc hóa học hoặc hoạt động nào thành tín hiệu điện hoặc tín hiệu điện thành bất kỳ loại hiện tượng vật lý hoặc hoạt động nào. Tất cả các phần tử trong bộ chuyển đổi dựa trên chất bán dẫn được kết hợp một cách không thể tách rời và cũng có thể bao gồm các vật liệu cần thiết được gắn một cách không thể tách rời, nó đảm bảo cho cấu trúc hoặc chức năng của chúng.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_12A_I_DEF1', code: '', label: 'Chương 85 — Chú giải 12 a(i)(1)', section: 'XVI', chapter: '85', level: None, description: '(1) “Dựa trên chất bán dẫn” có nghĩa là được chế tạo hoặc sản xuất trên nền bán dẫn hoặc làm bằng vật liệu bán dẫn, được sản xuất bằng công nghệ bán dẫn, trong đó chất nền hoặc vật liệu bán dẫn đóng vai trò quan trọng và không thể thay thế đối với chức năng và hiệu suất của bộ chuyển đổi và hoạt động của nó dựa trên các đặc tính bán dẫn bao gồm các đặc tính vật lý, điện, hóa học và quang học.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_12A_I_DEF2', code: '', label: 'Chương 85 — Chú giải 12 a(i)(2)', section: 'XVI', chapter: '85', level: None, description: '(2) “Đại lượng vật lý hoặc đại lượng hóa học” liên quan đến các đại lượng như áp suất, sóng âm thanh, gia tốc, rung, chuyển động, phương hướng, sức căng, cường độ từ trường, cường độ điện trường, ánh sáng, phóng xạ, độ ẩm, dòng chảy, nồng độ hóa chất...'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_12A_I_DEF3', code: '', label: 'Chương 85 — Chú giải 12 a(i)(3)', section: 'XVI', chapter: '85', level: None, description: '(3) “Cảm biến dựa trên chất bán dẫn” là một loại thiết bị bán dẫn, bao gồm các cấu trúc vi điện tử hoặc cấu trúc cơ khí được chế tạo trong khối hoặc trên bề mặt chất bán dẫn và có chức năng dò tìm đại lượng vật lý hoặc hóa học và chuyển đổi thành các tín hiệu điện nhờ vào kết quả của sự thay đổi những thuộc tính điện hoặc sự dịch chuyển một cấu trúc cơ khí.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_12A_I_DEF4', code: '', label: 'Chương 85 — Chú giải 12 a(i)(4)', section: 'XVI', chapter: '85', level: None, description: '(4) “Cơ cấu chấp hành dựa trên chất bán dẫn” là một loại thiết bị bán dẫn, bao gồm các cấu trúc vi điện tử hoặc cấu trúc cơ khí được chế tạo trong khối hoặc trên bề mặt chất bán dẫn và có chức năng chuyển đổi tín hiệu điện thành chuyển động vật lý.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_12A_I_DEF5', code: '', label: 'Chương 85 — Chú giải 12 a(i)(5)', section: 'XVI', chapter: '85', level: None, description: '(5) “Thiết bị cộng hưởng dựa trên chất bán dẫn” là một loại thiết bị bán dẫn, bao gồm các cấu trúc vi điện tử hoặc cấu trúc cơ khí được chế tạo trong khối hoặc trên bề mặt chất bán dẫn và chúng có chức năng tạo ra dao động điện hoặc dao động cơ với một tần số xác định trước phụ thuộc vào hình dạng vật lý của các cấu trúc đó để đáp ứng với một đầu vào bên ngoài.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_12A_I_DEF6', code: '', label: 'Chương 85 — Chú giải 12 a(i)(6)', section: 'XVI', chapter: '85', level: None, description: '(6) “Thiết bị dao động dựa trên chất bán dẫn” là một loại thiết bị bán dẫn, bao gồm các cấu trúc vi điện tử hoặc cấu trúc cơ khí được chế tạo trong khối hoặc trên bề mặt chất bán dẫn và chúng có chức năng tạo ra dao động điện hoặc dao động cơ với một tần số xác định trước phụ thuộc vào hình dạng vật lý của các cấu trúc đó.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_12A_II', code: '', label: 'Chương 85 — Chú giải 12 a(ii)', section: 'XVI', chapter: '85', level: None, description: '(ii) “Đi-ốt phát quang (LED)” là thiết bị bán dẫn dựa trên vật liệu bán dẫn chuyển đổi năng lượng điện thành các tia có thể nhìn thấy, tia hồng ngoại hoặc tia cực tím, có hoặc không kết nối điện với nhau và có hoặc không kết hợp với đi-ốt bảo vệ. Đi-ốt phát quang (LED) thuộc nhóm 85.41 không kết hợp các phần tử với mục đích cung cấp nguồn hoặc điều khiển nguồn;'}) $$) as (v agtype);
