SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_12B_I', code: '', label: 'Chương 85 — Chú giải 12 b(i)', section: 'XVI', chapter: '85', level: None, description: '(i) Mạch tích hợp đơn khối trong đó các phần tử của mạch điện (đi-ốt, tranzito, điện trở, tụ điện, cuộn cảm...) được tạo (chủ yếu) trong khối đó và trên bề mặt của một vật liệu bán dẫn hoặc vật liệu bán dẫn kết hợp (ví dụ, silic đã kích tạp, gali asenua, silic-germani, indi photphua) và ở dạng liên kết chặt chẽ (không tách biệt);'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_12B_II', code: '', label: 'Chương 85 — Chú giải 12 b(ii)', section: 'XVI', chapter: '85', level: None, description: '(ii) Mạch tích hợp lai trong đó các phần tử thụ động (điện trở, tụ điện, cuộn cảm...), được tạo thành từ công nghệ màng mỏng hoặc màng dày và các phần tử chủ động (đi-ốt, tranzito, mạch tích hợp đơn khối ...), được tạo thành nhờ công nghệ bán dẫn, các phần tử này được kết nối không tách rời, bằng việc gắn kết với nhau hoặc bằng dây liên kết, trên một tấm cách điện đơn (thủy tinh, gốm sứ...). Những mạch này cũng có thể kể cả các linh kiện bố trí riêng biệt;'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_12B_III', code: '', label: 'Chương 85 — Chú giải 12 b(iii)', section: 'XVI', chapter: '85', level: None, description: '(iii) Mạch tích hợp đa chíp bao gồm hai hoặc nhiều mạch tích hợp đơn khối gắn với nhau không tách rời, có hoặc không gắn một hoặc nhiều tấm cách điện, có hoặc không có khung dây, nhưng không gắn phần tử mạch chủ động hoặc thụ động khác.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_12B_IV', code: '', label: 'Chương 85 — Chú giải 12 b(iv)', section: 'XVI', chapter: '85', level: None, description: '(iv) Mạch tích hợp đa thành phần (MCOs): sự kết hợp một hoặc nhiều mạch tích hợp đơn khối, lai hoặc đa chíp có ít nhất một trong những thành phần sau: cảm biến, cơ cấu chấp hành, bộ dao động, bộ cộng hưởng nền silic, hoặc kết hợp giữa chúng, hoặc các thành phần thực hiện chức năng của hàng hóa thuộc nhóm 85.32, 85.33, 85.41, hoặc cuộn cảm thuộc nhóm 85.04, được định hình với mọi mục đích thành một khối duy nhất không thể tách rời giống một bảng mạch tích hợp, như thành phần được lắp ráp trên tấm mạch in (PCB) hoặc trên vật mang khác, thông qua việc kết nối các chân cắm, dây dẫn (leads), khớp nối cầu (balls), dải nối (lands), mấu nối (bumps), hoặc đế/đệm nối (pads).'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_12B_IV_DEF1', code: '', label: 'Chương 85 — Chú giải 12 b(iv)(1)', section: 'XVI', chapter: '85', level: None, description: '1. “Thành phần” có thể riêng biệt, được chế tạo độc lập, sau đó được lắp ráp lên mạch tích hợp đa thành phần (MCO), hoặc được tích hợp trong những thành phần khác.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_12B_IV_DEF2', code: '', label: 'Chương 85 — Chú giải 12 b(iv)(2)', section: 'XVI', chapter: '85', level: None, description: '2. “Nền silic” nghĩa là được đặt trên một nền silic, hoặc được làm bằng vật liệu silic, hoặc được chế tạo trên khuôn mạch tích hợp (integrated circuit die).'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_12B_IV_DEF3A', code: '', label: 'Chương 85 — Chú giải 12 b(iv)(3)(a)', section: 'XVI', chapter: '85', level: None, description: '3. (a) “Cảm biến nền silic” bao gồm những cấu trúc vi điện tử hoặc cấu trúc cơ khí được chế tạo trong khối hoặc trên bề mặt bán dẫn và chúng có chức năng dò tìm đại lượng vật lý hoặc đại lượng hóa học và chuyển đổi thành những tín hiệu điện nhờ vào kết quả của sự thay đổi những thuộc tính điện hoặc sự dịch chuyển một cấu trúc cơ khí. “Đại lượng vật lý hoặc đại lượng hóa học” liên quan đến các đại lượng như áp suất, sóng âm thanh, gia tốc, rung, chuyển động, phương hướng, sức căng, cường độ từ trường, cường độ điện trường, ánh sáng, phóng xạ, độ ẩm, dòng chảy, nồng độ hóa chất...'}) $$) as (v agtype);
