SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_NOTE_12_PRIORITY', code: '', label: 'Chương 85 — Chú giải 12 priority', section: 'XVI', chapter: '85', level: None, description: 'Để phân loại những mặt hàng được định nghĩa trong Chú giải này, các nhóm 85.41 và 85.42 được ưu tiên xem xét trước hết so với bất kỳ nhóm nào khác trong Danh mục hàng hóa, trừ các mặt hàng thuộc nhóm 85.23.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_SUBNOTE_1', code: '', label: 'Chương 85 — Chú giải phân nhóm 1', section: 'XVI', chapter: '85', level: None, description: 'Phân nhóm 8525.81 chỉ bao gồm camera truyền hình, camera kỹ thuật số và camera ghi hình ảnh tốc độ cao có một hoặc nhiều đặc điểm sau: - tốc độ ghi trên 0,5 mm mỗi micro giây; - độ phân giải thời gian từ 50 nano giây trở xuống; - tốc độ khung hình trên 225.000 khung hình mỗi giây.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_SUBNOTE_2', code: '', label: 'Chương 85 — Chú giải phân nhóm 2', section: 'XVI', chapter: '85', level: None, description: 'Đối với phân nhóm 8525.82, camera truyền hình, camera kỹ thuật số và camera ghi hình ảnh được làm cứng bức xạ hoặc chịu bức xạ được thiết kế hoặc được che chắn để có thể hoạt động trong môi trường bức xạ cao. Các camera này được thiết kế để chịu được tổng lượng bức xạ ít nhất là 50 X 10^3Gy(silic) (5 X 10^6 RAD (silic)) mà không bị suy giảm hoạt động.'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_SUBNOTE_3', code: '', label: 'Chương 85 — Chú giải phân nhóm 3', section: 'XVI', chapter: '85', level: None, description: 'Phân nhóm 8525.83 bao gồm camera truyền hình, camera kỹ thuật số và camera ghi hình ảnh nhìn ban đêm sử dụng một ca-tốt quang điện (photocathode) để chuyển đổi ánh sáng có sẵn thành các điện tử (electrons), có thể được khuếch đại và chuyển đổi để mang lại hình ảnh nhìn thấy được. Phân nhóm này loại trừ camera ảnh nhiệt (thường thuộc phân nhóm 8525.89).'}) $$) as (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Subheading {id: 'SXVI-N-CH85_SUBNOTE_4', code: '', label: 'Chương 85 — Chú giải phân nhóm 4', section: 'XVI', chapter: '85', level: None, description: 'Phân nhóm 8527.12 chỉ gồm các loại máy cát sét có bộ khuếch đại lắp sẵn, không có loa lắp sẵn, có khả năng hoạt động không cần nguồn điện ngoài và kích thước không quá 170 mm x 100 mm x 45 mm.'}) $$) as (v agtype);
